import { StyleSheet } from "@/lib/pdf-primitives";

import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all table styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createTableStyles = (t: PdfcnTheme) => {
  const { spacing, borderRadius, fontWeights, typography } = t.primitives;
  const borderColor = t.colors.border;

  const hairline = 0.5;
  const rule = 1;
  const thick = 1.5;

  const cellPadV = spacing[2] - 2;
  const cellPadH = spacing[2] + 2;
  // eslint-disable-next-line prefer-destructuring
  const cellPadVCompact = spacing[0.5];
  // eslint-disable-next-line prefer-destructuring
  const cellPadHCompact = spacing[2];

  const rowDivider = {
    borderBottomColor: borderColor,
    borderBottomStyle: "solid" as const,
    borderBottomWidth: hairline,
  };

  return StyleSheet.create({
    cell: {
      flex: 1,
      justifyContent: "center",
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellBordered: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellBorderedBorder: {
      borderRightColor: borderColor,
      borderRightStyle: "solid",
      borderRightWidth: hairline,
    },

    cellCompact: {
      paddingHorizontal: cellPadHCompact,
      paddingVertical: cellPadVCompact,
    },

    cellFixed: {
      flexGrow: 0,
      flexShrink: 0,
      justifyContent: "center",
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellGridBorder: {
      borderRightColor: borderColor,
      borderRightStyle: "solid",
      borderRightWidth: hairline,
    },

    cellMinimal: {
      paddingHorizontal: spacing[2] - 2,
      paddingVertical: spacing[1] + 1,
    },

    cellPrimaryHeader: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellStriped: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: 1.2,
    },
    cellTextCompact: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      lineHeight: 1.2,
    },
    cellTextFooter: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    cellTextHeaderBordered: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.bold,
      lineHeight: 1.2,
    },
    cellTextHeaderCompact: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.6,
      lineHeight: 1.2,
      textTransform: "uppercase",
    },
    cellTextHeaderGrid: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    cellTextHeaderLine: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },

    cellTextHeaderMinimal: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.medium,
      lineHeight: 1.2,
    },
    cellTextHeaderPrimaryHeader: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.6,
      lineHeight: 1.2,
      textTransform: "uppercase",
    },
    cellTextHeaderStriped: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    row: {
      display: "flex",
      flexDirection: "row",
    },
    rowBordered: rowDivider,
    rowCompact: rowDivider,
    rowFooter: {
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: rule,
    },

    rowFooterStriped: {
      backgroundColor: t.colors.muted,
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: rule,
    },
    rowGrid: rowDivider,

    rowHeaderBordered: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },

    rowHeaderCompact: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderGrid: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },

    rowHeaderLine: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderMinimal: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderPrimaryHeader: {
      backgroundColor: t.colors.primary,
    },
    rowHeaderStriped: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowLine: rowDivider,

    rowMinimal: rowDivider,
    rowPrimaryHeader: rowDivider,

    rowStripe: {
      backgroundColor: t.colors.muted,
    },

    rowStriped: {},
    table: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    tableBordered: {
      borderBottomLeftRadius: borderRadius.sm,
      borderBottomRightRadius: borderRadius.sm,
      borderColor,
      borderStyle: "solid",
      borderTopLeftRadius: borderRadius.sm,
      borderTopRightRadius: borderRadius.sm,
      borderWidth: rule,
      overflow: "hidden" as const,
    },
    tableCompact: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },
    tableGrid: {
      borderBottomLeftRadius: borderRadius.md,
      borderBottomRightRadius: borderRadius.md,
      borderColor,
      borderStyle: "solid",
      borderTopLeftRadius: borderRadius.md,
      borderTopRightRadius: borderRadius.md,
      borderWidth: thick,
      overflow: "hidden" as const,
    },
    tableLine: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },
    tableMinimal: {
      paddingVertical: spacing[2],
    },

    tablePrimaryHeader: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },

    tableStriped: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: hairline,
    },
  });
};

import { NgTemplateOutlet } from "@angular/common";
import {
  Component,
  DestroyRef,
  booleanAttribute,
  computed,
  inject,
  input,
  signal,
} from "@angular/core";
import type { WritableSignal } from "@angular/core";

import {
  injectPdfcnTheme,
  mergePdfStyles,
} from "@/components/pdf/theme-provider";
import { FormeText, FormeView } from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

import { createTableStyles } from "./table.styles";
import type {
  TableCellProps,
  TableProps,
  TableRowProps,
  TableSectionProps,
  TableVariant,
} from "./table.types";

const cellStyles = (
  theme: PdfcnTheme,
  { header, footer, align, width, style, variant = "line", _last }: TableCellProps
) => {
  const styles = createTableStyles(theme);
  const cellStyles: Style[] =
    width === undefined
      ? [styles.cell]
      : [styles.cellFixed, { width } as Style];

  const cellVariantStyle = (
    {
      bordered: styles.cellBordered,
      compact: styles.cellCompact,
      minimal: styles.cellMinimal,
      "primary-header": styles.cellPrimaryHeader,
      striped: styles.cellStriped,
    } as Partial<Record<TableVariant, Style>>
  )[variant];
  if (cellVariantStyle) {
    cellStyles.push(cellVariantStyle);
  }

  if (variant === "grid" && !_last) {
    cellStyles.push(styles.cellGridBorder);
  } else if (variant === "bordered" && !_last) {
    cellStyles.push(styles.cellBorderedBorder);
  }

  if (align) {
    cellStyles.push({ textAlign: align } as Style);
  }

  const styleArray = style ? [...cellStyles, style] : cellStyles;

  let textStyle: Style = styles.cellText;
  if (header) {
    textStyle = {
      bordered: styles.cellTextHeaderBordered,
      compact: styles.cellTextHeaderCompact,
      grid: styles.cellTextHeaderGrid,
      line: styles.cellTextHeaderLine,
      minimal: styles.cellTextHeaderMinimal,
      "primary-header": styles.cellTextHeaderPrimaryHeader,
      striped: styles.cellTextHeaderStriped,
    }[variant];
  } else if (footer) {
    textStyle = styles.cellTextFooter;
  } else if (variant === "compact") {
    textStyle = styles.cellTextCompact;
  }

  return {
    cell: mergePdfStyles(styleArray),
    text: mergePdfStyles([
      textStyle,
      align ? { textAlign: align } : {},
      { margin: 0, padding: 0 },
    ]),
  };
};

const rowStyle = (
  theme: PdfcnTheme,
  { header, footer, stripe, style, variant = "line" }: TableRowProps
) => {
  const styles = createTableStyles(theme);
  const rowStyles: Style[] = [
    styles.row,
    {
      bordered: styles.rowBordered,
      compact: styles.rowCompact,
      grid: styles.rowGrid,
      line: styles.rowLine,
      minimal: styles.rowMinimal,
      "primary-header": styles.rowPrimaryHeader,
      striped: styles.rowStriped,
    }[variant],
  ];

  if (header) {
    rowStyles.push(
      {
        bordered: styles.rowHeaderBordered,
        compact: styles.rowHeaderCompact,
        grid: styles.rowHeaderGrid,
        line: styles.rowHeaderLine,
        minimal: styles.rowHeaderMinimal,
        "primary-header": styles.rowHeaderPrimaryHeader,
        striped: styles.rowHeaderStriped,
      }[variant]
    );
  }

  if (footer) {
    if (variant === "striped") {
      rowStyles.push(styles.rowFooterStriped);
    } else {
      rowStyles.push(styles.rowFooter);
    }
  }

  if (stripe && !header && !footer) {
    rowStyles.push(styles.rowStripe);
  }

  const styleArray = style ? [...rowStyles, style] : rowStyles;
  return mergePdfStyles(styleArray);
};

const tableStyle = (
  theme: PdfcnTheme,
  { style, variant = "line" }: TableProps
) => {
  const styles = createTableStyles(theme);
  const tableStyles: Style[] = [styles.table];

  tableStyles.push(
    {
      bordered: styles.tableBordered,
      compact: styles.tableCompact,
      grid: styles.tableGrid,
      line: styles.tableLine,
      minimal: styles.tableMinimal,
      "primary-header": styles.tablePrimaryHeader,
      striped: styles.tableStriped,
    }[variant]
  );

  const styleArray = style ? [...tableStyles, style] : tableStyles;
  return mergePdfStyles(styleArray);
};

/** Adds `item` to `list` in creation order and removes it on destroy. */
const register = <T>(list: WritableSignal<T[]>, item: T) => {
  list.update((items) => [...items, item]);
  inject(DestroyRef).onDestroy(() =>
    list.update((items) => items.filter((entry) => entry !== item))
  );
};

@Component({
  imports: [FormeView, NgTemplateOutlet],
  selector: "pdf-table",
  template: `
    <ng-template #rows><ng-content /></ng-template>
    @if (noWrap()) {
      <forme-view [wrap]="false">
        <forme-view [style]="tableStyle()"><ng-container [ngTemplateOutlet]="rows" /></forme-view>
      </forme-view>
    } @else {
      <forme-view [style]="tableStyle()"><ng-container [ngTemplateOutlet]="rows" /></forme-view>
    }
  `,
})
export class PdfTable {
  readonly variant = input<TableVariant>("line");
  readonly zebraStripe = input(false, { transform: booleanAttribute });
  readonly noWrap = input(false, { transform: booleanAttribute });
  readonly style = input<TableProps["style"]>();

  /** Rows inside `<pdf-table-body>`, in document order. */
  readonly bodyRows = signal<PdfTableRow[]>([]);
  readonly zebra = computed(
    () => this.variant() === "striped" || this.zebraStripe()
  );

  private readonly theme = injectPdfcnTheme();
  protected readonly tableStyle = computed(() =>
    tableStyle(this.theme(), { style: this.style(), variant: this.variant() })
  );
}

@Component({
  imports: [FormeView],
  selector: "pdf-table-header",
  template: `<forme-view [style]="style()"><ng-content /></forme-view>`,
})
export class PdfTableHeader {
  readonly style = input<TableSectionProps["style"]>();
}

@Component({
  imports: [FormeView],
  selector: "pdf-table-body",
  template: `<forme-view [style]="style()"><ng-content /></forme-view>`,
})
export class PdfTableBody {
  readonly style = input<TableSectionProps["style"]>();
}

@Component({
  imports: [FormeView],
  selector: "pdf-table-footer",
  template: `<forme-view [style]="style()"><ng-content /></forme-view>`,
})
export class PdfTableFooter {
  readonly style = input<TableSectionProps["style"]>();
}

/** Inside a `<pdf-table>`, the table's variant and zebra striping apply. */
@Component({
  imports: [FormeView],
  selector: "pdf-table-row",
  template: `<forme-view [wrap]="false" [style]="rowStyle()"><ng-content /></forme-view>`,
})
export class PdfTableRow {
  readonly header = input(false, { transform: booleanAttribute });
  readonly footer = input(false, { transform: booleanAttribute });
  readonly stripe = input(false, { transform: booleanAttribute });
  readonly variant = input<TableVariant>("line");
  readonly style = input<TableRowProps["style"]>();

  private readonly table = inject(PdfTable, { optional: true });
  readonly cells = signal<PdfTableCell[]>([]);
  readonly resolvedVariant = computed(
    () => this.table?.variant() ?? this.variant()
  );

  constructor() {
    if (this.table && inject(PdfTableBody, { optional: true })) {
      register(this.table.bodyRows, this);
    }
  }

  private readonly theme = injectPdfcnTheme();
  protected readonly rowStyle = computed(() =>
    rowStyle(this.theme(), {
      footer: this.footer(),
      header: this.header(),
      stripe: this.table
        ? this.table.zebra() && this.table.bodyRows().indexOf(this) % 2 === 1
        : this.stripe(),
      style: this.style(),
      variant: this.resolvedVariant(),
    })
  );
}

/** Inside a `<pdf-table-row>`, the row's `header`, `footer`, and variant apply. */
@Component({
  imports: [FormeText, FormeView],
  selector: "pdf-table-cell",
  template: `
    <forme-view [style]="styles().cell">
      <forme-text ifString [style]="styles().text"><ng-content /></forme-text>
    </forme-view>
  `,
})
export class PdfTableCell {
  readonly header = input(false, { transform: booleanAttribute });
  readonly footer = input(false, { transform: booleanAttribute });
  readonly align = input<TableCellProps["align"]>();
  readonly width = input<TableCellProps["width"]>();
  readonly variant = input<TableVariant>("line");
  readonly style = input<TableCellProps["style"]>();

  private readonly row = inject(PdfTableRow, { optional: true });

  constructor() {
    if (this.row) {
      register(this.row.cells, this);
    }
  }

  private readonly theme = injectPdfcnTheme();
  protected readonly styles = computed(() =>
    cellStyles(this.theme(), {
      _last: this.row?.cells().at(-1) === this,
      align: this.align(),
      footer: this.row ? this.row.footer() : this.footer(),
      header: this.row ? this.row.header() : this.header(),
      style: this.style(),
      variant: this.row ? this.row.resolvedVariant() : this.variant(),
      width: this.width(),
    })
  );
}

export const TABLE = [
  PdfTable,
  PdfTableHeader,
  PdfTableBody,
  PdfTableFooter,
  PdfTableRow,
  PdfTableCell,
] as const;

import type { PDFComponentProps } from "@/types/pdf-components";

/** Table visual style variant. */
export type TableVariant =
  | "line"
  | "grid"
  | "minimal"
  | "striped"
  | "compact"
  | "bordered"
  | "primary-header";

/**
 * Table container with visual style variants and optional zebra striping.
 * Props - `variant` | `zebraStripe` | `noWrap` | `children` | `style`
 * @see {@link TableProps}
 */
export interface TableProps extends PDFComponentProps {
  /**
   * @default 'line'
   */
  variant?: TableVariant;
  /**
   * @default false
   */
  zebraStripe?: boolean;
  /**
   * @default false
   */
  noWrap?: boolean;
}

export type TableSectionProps = PDFComponentProps;

/**
 * Table row with optional header, footer, and stripe states.
 * Props - `header` | `footer` | `stripe` | `variant` | `children` | `style`
 * @see {@link TableRowProps}
 */
export interface TableRowProps extends PDFComponentProps {
  header?: boolean;
  footer?: boolean;
  stripe?: boolean;
  variant?: TableVariant;
}

/**
 * Table cell with alignment, width, and header or footer text styling.
 * Props - `header` | `footer` | `align` | `width` | `variant` | `_last` | `children` | `style`
 * @see {@link TableCellProps}
 */
export interface TableCellProps extends PDFComponentProps {
  header?: boolean;
  footer?: boolean;
  align?: "left" | "center" | "right";
  width?: string | number;
  variant?: TableVariant;
  _last?: boolean;
}
